<?php require_once __DIR__.'/../config.php';$me=require_admin();$users=data_load('users.json');$logs=array_reverse(data_load('logs.json'));$threads=data_load('threads.json');if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['user_id']??0);$action=$_POST['mod_action']??'ban_both';$reason=trim($_POST['reason']??'Нарушение правил');$days=(int)($_POST['days']??7);foreach($users as &$target){if((int)$target['id']!==$id)continue;if($action==='unban'){$target['banned_until']=null;$target['ban_reason']='';log_action('Снятие бана',$target['username'],$reason);}else{$until=$days===0?'permanent':date('c',time()+$days*86400);if($action==='ban'||$action==='ban_both'){$target['banned_until']=$until;$target['ban_reason']=$reason;}if($action==='ban_ip'||$action==='ban_both'){$bans=data_load('bans.json');$bans[]=['id'=>count($bans)+1,'type'=>'ip','value'=>$_SERVER['REMOTE_ADDR'],'until'=>$until,'reason'=>$reason,'user_id'=>$id];data_save('bans.json',$bans);}log_action($action,$target['username'],$reason);}break;}unset($target);data_save('users.json',$users);header('Location:index.php');exit;}?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Админ-панель — GREFFRLEND</title><link rel="stylesheet" href="../style.css"></head><body><header class="top"><div class="wrap nav"><a class="logo" href="../index.php">GREFFRLEND</a><nav><a href="../index.php">Форум</a><a href="users.php">Пользователи</a><a href="bans.php">Баны</a></nav></div></header><main class="wrap"><h1>Админ-панель</h1><div class="grid"><div class="card"><h2>Статистика</h2><p>Пользователей: <b><?=count($users)?></b></p><p>Тем: <b><?=count($threads)?></b></p><p>Логов: <b><?=count($logs)?></b></p></div><div class="card"><h2>Модерация</h2><p>Выбери пользователя ниже и назначь бан аккаунта, IP-бан или оба.</p></div></div><h2>Пользователи</h2><?php foreach($users as $u):?><div class="card thread"><div><b><?=e($u['username'])?></b><div class="muted"><?=e($u['email'])?> · <?=e($u['role'])?></div></div><details><summary class="btn small">Наказать</summary><form method="post" class="form" style="min-width:250px"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="user_id" value="<?=$u['id']?>"><select name="mod_action"><option value="ban_both">Бан + IP</option><option value="ban">Бан аккаунта</option><option value="ban_ip">IP-бан</option><option value="unban">Снять бан</option></select><select name="days"><option value="1">1 день</option><option value="3">3 дня</option><option value="7">7 дней</option><option value="14">14 дней</option><option value="30">30 дней</option><option value="0">Навсегда</option></select><input name="reason" placeholder="Причина" required><button class="btn">Применить</button></form></details></div><?php endforeach;?></main></body></html>